  "critique": [
    {
      "design": "r1A",
      "good": "The columns have a balanced rhythm, the headers remain intact, and the compact Chinese and Korean terms stay on one line. The two taller rows are easy to follow across the table.",
      "problems": "The longest Japanese term wraps, as do the two longest English terms and the longest Arabic term. The final row has several short lines, making it feel busier than the rows above.",
      "cause": "The Japanese column provides 79px of text space against a 93px one-line requirement. English and Arabic provide 104px and 73px respectively, less than their longest one-line terms require."
    },
    {
      "design": "r1B",
      "good": "The wider Japanese and Arabic columns give those translations more room, while the headers and English words remain intact.",
      "problems": "Korean terms wrap in both of the taller rows, creating narrow fragments. Japanese still wraps in the final row, so the extra width there has not kept its longest term together.",
      "cause": "The 75px Korean column provides only 54px of text space, below the 64px needed for its longest term. The 110px Japanese column provides 89px, just short of the 93px needed."
    },
    {
      "design": "r1C",
      "good": "The wider English column gives the English entries a more comfortable measure, and the Arabic column is slightly more generous than in r1A.",
      "problems": "Chinese and Korean both break into short fragments in the longer rows, while Japanese also wraps in the final row. This makes the middle of the table look crowded and weakens the horizontal reading rhythm.",
      "cause": "The 70px Chinese and 75px Korean columns provide 49px and 54px of text space, below their respective 54px and 64px one-line requirements. The 100px Japanese column also falls short of its longest term."
    }
  ],
  "done": false,
